package lost_and_found.app.auth.service;

import java.util.Map;
import java.util.function.Function;

import org.springframework.security.core.userdetails.UserDetails;

import io.jsonwebtoken.Claims;

/**
 * A interface that defines how to interact with jwts generated by this application.
 */
public interface JwtService {
    /**
     * A funtion that gets the username from the token given.
     * @param token the token given.
     * @return the username of the user who the token belongs to.
     */
    String extractUsername(String token);
    /**
     * Extracts a claim from the given jwt token.
     * @param <T> the type of the claim we want to extract.
     * @param token the given token.
     * @param resolver a function that takes in a Claim object and return the corresponding claim.
     * @return the claim we want.
     */
    <T> T extractClaim(String token, Function<Claims, T> resolver);
    /**
     * Generates a token with no extra claims.
     * @param userDetails the user's data we will generate a claim from.
     * @return a token the containing user's data.
     */
    String generateToken(UserDetails userDetails);
    /**
     * Generates a token with extra claims defined by us.
     * @param extraClaims the extra claims we want to put into the user's token.
     * @param userDetails the user's data we will generate a claim from.
     * @returna token the containing user's data along with the extra claims defined by us.
     */
    String generateToken(Map<String, Object> extraClaims, UserDetails userDetails);

    /**
     * Generates a token that expires after {@code ttlMs} instead of the default expiry.
     * Used for short-lived tokens such as WebSocket tickets.
     * @param extraClaims claims to embed, e.g. the token type.
     * @param userDetails the user the token belongs to.
     * @param ttlMs lifetime of the token in milliseconds.
     * @return the signed token.
     */
    String generateShortLivedToken(Map<String, Object> extraClaims, UserDetails userDetails, long ttlMs);
    /**
     * Checks if a token is valid.
     * @param token the token we are checking.
     * @param userDetails the user's data we will be checking against.
     * @return true if the token is valid, else false.
     */
    boolean isTokenValid(String token, UserDetails userDetails);
    /**
     * Get the expiration time for a JWT.
     * @return expiration time of type long
     */
    long getExpirationTime();
    /**
     * Gets the JTI ((J)son web (T)oken (I)d)
     * @param token the token to get the id from
     * @return the JTI of the token given
     */
    String extractJti(String token);
}
